#!/usr/bin/env python3
"""
A small WSDL-to-Go generator reimplemented for the benchmark from observed
behaviour of the supplied executable.  It intentionally has no third-party
runtime dependencies.
"""
from __future__ import annotations

import os
import sys
import re
import html
import ssl
import shutil
import subprocess
import urllib.request
import urllib.parse
import xml.etree.ElementTree as ET
from dataclasses import dataclass, field
from collections import OrderedDict, defaultdict
from typing import Dict, List, Optional, Tuple, Iterable, Any

XSD_NS = "http://www.w3.org/2001/XMLSchema"
WSDL_NS = "http://schemas.xmlsoap.org/wsdl/"

GO_KEYWORDS = {
    "break", "default", "func", "interface", "select", "case", "defer", "go",
    "map", "struct", "chan", "else", "goto", "package", "switch", "const",
    "fallthrough", "if", "range", "type", "continue", "for", "import", "return",
    "var",
}

BUILTIN_MAP = {
    "string": "string",
    "normalizedString": "string",
    "token": "string",
    "language": "string",
    "Name": "string",
    "NMTOKEN": "string",
    "NMTOKENS": "string",
    "ID": "string",
    "IDREF": "string",
    "IDREFS": "string",
    "QName": "string",
    "boolean": "bool",
    "bool": "bool",
    "decimal": "float64",
    "double": "float64",
    "float": "float32",
    "int": "int32",
    "integer": "int32",
    "long": "int64",
    "short": "int16",
    "byte": "int8",
    "unsignedByte": "byte",
    "unsignedShort": "uint16",
    "unsignedInt": "uint32",
    "unsignedLong": "uint64",
    "nonNegativeInteger": "uint32",
    "dateTime": "soap.XSDDateTime",
    "date": "soap.XSDDate",
    "time": "soap.XSDTime",
    "base64Binary": "[]byte",
    "hexBinary": "[]byte",
    "anyType": "AnyType",
    "anyURI": "AnyURI",
    "NCName": "NCName",
}

DATE_WRAPPERS = {
    "soap.XSDDate": ("xd", "soap.XSDDate"),
    "soap.XSDDateTime": ("xdt", "soap.XSDDateTime"),
    "soap.XSDTime": ("xt", "soap.XSDTime"),
}


def local_name(tag: str) -> str:
    if tag is None:
        return ""
    if "}" in tag:
        return tag.rsplit("}", 1)[1]
    if ":" in tag:
        return tag.split(":", 1)[1]
    return tag


def namespace(tag: str) -> str:
    if tag and tag.startswith("{") and "}" in tag:
        return tag[1:].split("}", 1)[0]
    return ""


def child_elems(e: ET.Element, lname: Optional[str] = None) -> List[ET.Element]:
    if lname is None:
        return list(e)
    return [c for c in list(e) if local_name(c.tag) == lname]


def first_child(e: ET.Element, *names: str) -> Optional[ET.Element]:
    for c in list(e):
        if local_name(c.tag) in names:
            return c
    return None


def descendants(e: ET.Element, lname: str) -> List[ET.Element]:
    return [x for x in e.iter() if local_name(x.tag) == lname]


def qlocal(q: Optional[str]) -> str:
    if not q:
        return ""
    if q.startswith("{"):
        return local_name(q)
    if ":" in q:
        return q.split(":", 1)[1]
    return q


def qprefix(q: Optional[str]) -> str:
    if not q or q.startswith("{"):
        return ""
    if ":" in q:
        return q.split(":", 1)[0]
    return ""


def is_url(s: str) -> bool:
    return s.startswith("http://") or s.startswith("https://")


def clean_doc_text(s: str) -> str:
    if s is None:
        return ""
    # ElementTree collapses child markup poorly with itertext; callers pass joined
    # text.  Normalize indentation the way the observed generator effectively does.
    s = s.replace("\r\n", "\n").replace("\r", "\n")
    lines = s.split("\n")
    # Trim leading/trailing blank lines.
    while lines and not lines[0].strip():
        lines.pop(0)
    while lines and not lines[-1].strip():
        lines.pop()
    if not lines:
        return ""
    # Remove common indentation from nonblank lines after XML indentation.
    indents = [len(re.match(r"^[ \t]*", ln).group(0)) for ln in lines if ln.strip()]
    cut = min(indents) if indents else 0
    if cut:
        lines = [ln[cut:] if len(ln) >= cut else ln for ln in lines]
    return "\n".join(ln.rstrip() for ln in lines)


def documentation(e: ET.Element) -> str:
    for ann in child_elems(e, "annotation"):
        for doc in child_elems(ann, "documentation"):
            return clean_doc_text("".join(doc.itertext()))
    return ""


def sanitize_identifier(s: str, for_enum: bool = False, public: bool = True) -> str:
    if s is None:
        s = ""
    if s == "":
        return ""
    # XML names in the bundled tests are already identifier-like.  For safety,
    # convert non-identifier runes to underscores but preserve existing underscores.
    out = []
    for ch in s:
        if ch.isalnum() or ch == "_":
            out.append(ch)
        elif ch in "-.":
            out.append("_")
        elif ch.isspace():
            # For schema identifiers, title-case words separated by spaces.
            out.append("_")
        else:
            out.append("_")
    res = "".join(out)
    # Drop repeated underscores introduced by unusual punctuation, but not the
    # meaningful single underscores in names like GetWorkshops_V2.
    res = re.sub(r"_+", "_", res).strip("_") or "_"
    if public and res and res[0].isalpha():
        res = res[0].upper() + res[1:]
    if res and res[0].isdigit():
        res = "_" + res
    if s in GO_KEYWORDS or res in GO_KEYWORDS:
        res += "_"
    return res


def go_name(s: str, public: bool = True) -> str:
    return sanitize_identifier(s, public=public)


def private_name(s: str) -> str:
    n = go_name(s, True)
    if not n:
        return n
    return n[0].lower() + n[1:]


def enum_suffix(value: str, public: bool = True) -> str:
    if value == "":
        return "EmptyString" if public else "emptyString"
    out = []
    cap_next = public
    for ch in value:
        if ch.isspace():
            cap_next = True
            continue
        if ch == "-" or ch == "." or ch == "/" or ch == ":":
            if not out or out[-1] != "_":
                out.append("_")
            cap_next = False
            continue
        if ch.isalnum() or ch == "_":
            if cap_next and ch.isalpha():
                out.append(ch.upper())
            else:
                out.append(ch)
            cap_next = False
        else:
            if not out or out[-1] != "_":
                out.append("_")
            cap_next = False
    res = "".join(out).strip("_") or "Value"
    if public and res and res[0].isalpha():
        res = res[0].upper() + res[1:]
    return res


def quote_go_string(s: str) -> str:
    # Use Go double-quoted string escaping.
    return '"' + s.replace('\\', '\\\\').replace('"', '\\"').replace('\n', '\\n').replace('\t', '\\t') + '"'


@dataclass
class SchemaThing:
    elem: ET.Element
    name: str
    ns: str
    kind: str
    order: int


@dataclass
class Part:
    name: str
    element: str = ""
    typ: str = ""


@dataclass
class Message:
    name: str
    parts: List[Part]


@dataclass
class Operation:
    name: str
    input_msg: str = ""
    output_msg: str = ""
    doc: str = ""


@dataclass
class PortType:
    name: str
    operations: List[Operation]


@dataclass
class LoadedDoc:
    text: str
    root: ET.Element
    base: str
    is_url: bool


class WsdlModel:
    def __init__(self, text: str, root: ET.Element, source: str, docs: List[LoadedDoc], make_public: bool = True):
        self.text = text
        self.root = root
        self.source = source
        self.docs = docs
        self.make_public = make_public
        self.prefix_map: Dict[str, str] = {}
        self.simple_types: List[SchemaThing] = []
        self.complex_types: List[SchemaThing] = []
        self.elements: List[SchemaThing] = []
        self.attributes: List[SchemaThing] = []
        self.simple_by_name: Dict[str, SchemaThing] = {}
        self.complex_by_name: Dict[str, SchemaThing] = {}
        self.element_by_name: Dict[str, SchemaThing] = {}
        self.attribute_by_name: Dict[str, SchemaThing] = {}
        self.messages: "OrderedDict[str, Message]" = OrderedDict()
        self.port_types: List[PortType] = []
        self.actions_by_port: Dict[str, Dict[str, str]] = defaultdict(dict)
        self.xmlname_for_type: Dict[str, Tuple[str, str]] = {}
        self._order = 0
        self._parse()
        self._assign_xmlnames()

    def _add_thing(self, collection: List[SchemaThing], mapping: Dict[str, SchemaThing], elem: ET.Element, ns: str, kind: str):
        name = elem.attrib.get("name", "")
        if not name:
            return
        self._order += 1
        thing = SchemaThing(elem=elem, name=name, ns=ns, kind=kind, order=self._order)
        collection.append(thing)
        mapping.setdefault(name, thing)

    def _parse(self):
        # Include schemas from the main WSDL and loaded imported XSDs.  The main
        # document is first, matching observed missing-import behaviour/logging.
        for doc in self.docs:
            root = doc.root
            schemas = []
            if local_name(root.tag) == "schema":
                schemas = [root]
            else:
                for types in child_elems(root, "types"):
                    schemas.extend([c for c in list(types) if local_name(c.tag) == "schema"])
                # Some WSDLs have nested schema descendants; keep direct first and
                # fall back to descendants if no direct schemas were found.
                if not schemas:
                    schemas = [e for e in root.iter() if local_name(e.tag) == "schema"]
            for schema in schemas:
                ns = schema.attrib.get("targetNamespace", "")
                for c in list(schema):
                    ln = local_name(c.tag)
                    if ln == "simpleType" and c.attrib.get("name"):
                        self._add_thing(self.simple_types, self.simple_by_name, c, ns, "simple")
                    elif ln == "element" and c.attrib.get("name"):
                        self._add_thing(self.elements, self.element_by_name, c, ns, "element")
                    elif ln == "complexType" and c.attrib.get("name"):
                        self._add_thing(self.complex_types, self.complex_by_name, c, ns, "complex")
                    elif ln == "attribute" and c.attrib.get("name"):
                        self._add_thing(self.attributes, self.attribute_by_name, c, ns, "attribute")

        # WSDL messages, port types, and bindings come from the main WSDL root.
        for c in list(self.root):
            if local_name(c.tag) == "message":
                parts = []
                for p in child_elems(c, "part"):
                    parts.append(Part(name=p.attrib.get("name", ""), element=p.attrib.get("element", ""), typ=p.attrib.get("type", "")))
                self.messages[c.attrib.get("name", "")] = Message(c.attrib.get("name", ""), parts)

        for pt in [c for c in list(self.root) if local_name(c.tag) == "portType"]:
            ops: List[Operation] = []
            for op in child_elems(pt, "operation"):
                inp = first_child(op, "input")
                out = first_child(op, "output")
                ops.append(Operation(
                    name=op.attrib.get("name", ""),
                    input_msg=qlocal(inp.attrib.get("message", "")) if inp is not None else "",
                    output_msg=qlocal(out.attrib.get("message", "")) if out is not None else "",
                    doc=documentation(op),
                ))
            self.port_types.append(PortType(pt.attrib.get("name", ""), ops))

        # Binding actions keyed by binding's portType.  Match observed behaviour
        # where HTTP GET/POST portTypes with the same operation names do not reuse
        # SOAP binding actions from the SOAP portType.
        for b in [c for c in list(self.root) if local_name(c.tag) == "binding"]:
            ptype = qlocal(b.attrib.get("type", ""))
            if not ptype:
                continue
            for op in child_elems(b, "operation"):
                action = None
                for cc in list(op):
                    if local_name(cc.tag) == "operation" and "soapAction" in cc.attrib:
                        action = cc.attrib.get("soapAction", "")
                        break
                if action is not None:
                    self.actions_by_port[ptype][op.attrib.get("name", "")] = action

    def is_builtin_q(self, q: str) -> bool:
        loc = qlocal(q)
        pref = qprefix(q)
        if loc in BUILTIN_MAP:
            # Unprefixed schema built-ins (common in WSDLs with default XSD ns)
            # and usual xs/xsd/s prefixes are built-ins.
            if pref in ("", "xs", "xsd", "s"):
                return True
        return False

    def builtin_go(self, q: str) -> str:
        return BUILTIN_MAP.get(qlocal(q), go_name(qlocal(q), True))

    def type_name_for_q(self, q: str, prefer_underlying_element: bool = False) -> str:
        loc = qlocal(q)
        if not loc:
            return "AnyType"
        if self.is_builtin_q(q):
            return self.builtin_go(q)
        # If a QName points to a global element (e.g. ref), resolve to that
        # element's Go type; otherwise use the QName local as a schema type.
        if prefer_underlying_element and loc in self.element_by_name:
            return self.element_go_type(self.element_by_name[loc], for_message=True)
        return go_name(loc, self.make_public)

    def is_known_named_type(self, loc: str) -> bool:
        return loc in self.simple_by_name or loc in self.complex_by_name or loc in self.element_by_name

    def element_go_type(self, thing: SchemaThing, for_message: bool = False) -> str:
        e = thing.elem
        name = thing.name
        if "type" in e.attrib:
            q = e.attrib.get("type", "")
            loc = qlocal(q)
            if self.is_builtin_q(q):
                return go_name(name, self.make_public) if not for_message else go_name(name, self.make_public)
            # For messages, observed code uses the underlying named type for
            # element aliases (Req -> Derived, CreateImage -> CreateImageType).
            if for_message:
                return go_name(loc, self.make_public)
            # For declarations, the element itself is a type alias when the Go
            # names differ; if names are equal, no separate type is generated.
            return go_name(name, self.make_public)
        if first_child(e, "complexType") is not None or first_child(e, "simpleType") is not None:
            return go_name(name, self.make_public)
        if "ref" in e.attrib:
            ref = qlocal(e.attrib.get("ref", ""))
            if ref in self.element_by_name:
                return self.element_go_type(self.element_by_name[ref], for_message=for_message)
            return go_name(ref, self.make_public)
        return go_name(name, self.make_public)

    def message_type(self, msg_name: str, warn: bool = True) -> str:
        if not msg_name or msg_name not in self.messages:
            return "EmptyString"
        msg = self.messages[msg_name]
        if not msg.parts:
            if warn:
                print(f"🍀  [WARN] {msg.name} message doesn't have any parts, ignoring message...")
            return "EmptyString"
        p = msg.parts[0]
        if p.element:
            loc = qlocal(p.element)
            if loc in self.element_by_name:
                return self.element_go_type(self.element_by_name[loc], for_message=True)
            return go_name(loc, self.make_public)
        if p.typ:
            if self.is_builtin_q(p.typ):
                # Operation parameters are pointers in the generated interface;
                # built-ins need a named Go identifier, not raw string/int.
                return go_name(qlocal(p.typ), self.make_public)
            return go_name(qlocal(p.typ), self.make_public)
        return "EmptyString"

    def _assign_xmlnames(self):
        # Global elements with inline complex types get their own XMLName.
        for thing in self.elements:
            e = thing.elem
            if first_child(e, "complexType") is not None:
                self.xmlname_for_type[go_name(thing.name, self.make_public)] = (thing.ns, thing.name)
            elif "type" in e.attrib:
                q = e.attrib.get("type", "")
                loc = qlocal(q)
                if (not self.is_builtin_q(q)) and loc in self.complex_by_name and go_name(loc, self.make_public) != go_name(thing.name, self.make_public):
                    self.xmlname_for_type.setdefault(go_name(loc, self.make_public), (thing.ns, thing.name))
        # Local element references sometimes seed XMLName for named complex types.
        # The observed generator does this for many wrapper/domain types.  We use a
        # conservative heuristic: same name ignoring first-letter case, or common
        # wrapper-ish names that are not generic scalar holders.
        generic_skip = {"IdentifiedString", "Range", "ValueRPM", "Color", "BaseRequest", "BaseResponse"}
        for ct in self.complex_types:
            for elem in self._iter_local_elements(ct.elem):
                q = elem.attrib.get("type") or elem.attrib.get("ref") or ""
                loc = qlocal(q)
                if loc in self.complex_by_name:
                    g = go_name(loc, self.make_public)
                    if g in self.xmlname_for_type or g in generic_skip:
                        continue
                    en = elem.attrib.get("name") or qlocal(elem.attrib.get("ref", ""))
                    if not en:
                        continue
                    if en.lower() == loc.lower() or en in {"basePrice", "installed", "price", "category", "definition", "responseStatus", "accountInfo"}:
                        self.xmlname_for_type.setdefault(g, (ct.ns, en))

    def _iter_local_elements(self, e: ET.Element) -> Iterable[ET.Element]:
        for x in e.iter():
            if x is e:
                continue
            if local_name(x.tag) == "element":
                # skip global elements by checking whether parent traversal is not
                # available; caller passes a complex type, so all are local.
                yield x


class Generator:
    def __init__(self, model: WsdlModel, package: str):
        self.m = model
        self.package = package
        self.lines: List[str] = []

    def emit(self, s: str = ""):
        self.lines.append(s)

    def render(self) -> str:
        self.lines = []
        self.header()
        for st in self.m.simple_types:
            self.render_simple_type(st, global_decl=True)
        for el in self.m.elements:
            self.render_global_element(el)
        for ct in self.m.complex_types:
            self.render_complex_type(ct)
        for pt in self.m.port_types:
            self.render_port_type(pt)
        return "\n".join(self.lines).rstrip() + "\n"

    def header(self):
        self.emit("// Code generated by gowsdl DO NOT EDIT.")
        self.emit("")
        self.emit(f"package {self.package}")
        self.emit("")
        self.emit("import (")
        self.emit('\t"context"')
        self.emit('\t"encoding/xml"')
        self.emit('\t"github.com/hooklift/gowsdl/soap"')
        self.emit('\t"time"')
        self.emit(")")
        self.emit("")
        self.emit('// against "unused imports"')
        self.emit("var _ time.Time")
        self.emit("var _ xml.Name")
        self.emit("")
        self.emit("type AnyType struct {")
        self.emit('\tInnerXML string `xml:",innerxml"`')
        self.emit("}")
        self.emit("")
        self.emit("type AnyURI string")
        self.emit("")
        self.emit("type NCName string")
        self.emit("")

    def emit_doc(self, e: ET.Element, indent: str = ""):
        doc = documentation(e)
        if not doc:
            return
        for ln in doc.split("\n"):
            if ln.strip():
                self.emit(f"{indent}// {ln.strip()}")
            else:
                self.emit(f"{indent}//")
        self.emit("")

    def simple_base(self, st_elem: ET.Element) -> Tuple[str, Optional[ET.Element], Optional[ET.Element]]:
        # Return Go base type, restriction element if any, list element if any.
        restriction = first_child(st_elem, "restriction")
        list_el = first_child(st_elem, "list")
        if restriction is not None:
            base = restriction.attrib.get("base", "string")
            return self.go_base_for_simple_base(base), restriction, None
        if list_el is not None:
            item = list_el.attrib.get("itemType", "string")
            base = self.go_base_for_simple_base(item)
            return "[]" + base, None, list_el
        union_el = first_child(st_elem, "union")
        if union_el is not None:
            return "string", None, None
        return "string", None, None

    def go_base_for_simple_base(self, q: str) -> str:
        if self.m.is_builtin_q(q):
            loc = qlocal(q)
            # Some built-ins intentionally remain named undefined wrappers in the
            # observed program.
            return BUILTIN_MAP.get(loc, go_name(loc, True))
        return go_name(qlocal(q), self.m.make_public)

    def render_simple_type(self, st: SchemaThing, global_decl: bool = True, forced_name: Optional[str] = None):
        name = forced_name or go_name(st.name, self.m.make_public)
        self.emit_doc(st.elem)
        base, restriction, list_el = self.simple_base(st.elem)
        self.emit(f"type {name} {base}")
        enums = []
        if restriction is not None:
            enums = [e for e in child_elems(restriction, "enumeration")]
        if enums:
            self.emit("")
            self.emit("const (")
            for enum in enums:
                val = enum.attrib.get("value", "")
                doc = documentation(enum)
                if doc:
                    self.emit("")
                    for ln in doc.split("\n"):
                        self.emit(f"\t// {ln.strip()}" if ln.strip() else "\t//")
                cname = name + enum_suffix(val, self.m.make_public)
                self.emit(f"\t{cname} {name} = {quote_go_string(val)}")
                self.emit("")
            # Remove trailing blank before close? gofmt keeps one if present less
            # predictably; observed output has a blank between consts, not before
            # close after gofmt.  Let gofmt normalize.
            if self.lines and self.lines[-1] == "":
                self.lines.pop()
            self.emit(")")
        self.emit("")

    def render_date_methods(self, name: str, base_go: str):
        if base_go not in DATE_WRAPPERS:
            return
        recv, soaptype = DATE_WRAPPERS[base_go]
        self.emit("")
        self.emit(f"func ({recv} {name}) MarshalXML(e *xml.Encoder, start xml.StartElement) error {{")
        self.emit(f"\treturn {soaptype}({recv}).MarshalXML(e, start)")
        self.emit("}")
        self.emit("")
        self.emit(f"func ({recv} *{name}) UnmarshalXML(d *xml.Decoder, start xml.StartElement) error {{")
        self.emit(f"\treturn (*{soaptype})({recv}).UnmarshalXML(d, start)")
        self.emit("}")

    def render_global_element(self, el: SchemaThing):
        e = el.elem
        name = go_name(el.name, self.m.make_public)
        st = first_child(e, "simpleType")
        ct = first_child(e, "complexType")
        if st is not None:
            fake = SchemaThing(st, el.name, el.ns, "simple", el.order)
            self.render_simple_type(fake, forced_name=name)
            return
        if ct is not None:
            self.emit_doc(e)
            self.emit(f"type {name} struct {{")
            self.emit(f"\tXMLName xml.Name `xml:\"{el.ns} {el.name}\"`")
            self.render_complex_body(ct, el.ns, indent="\t", skip_xmlname=True)
            self.emit("}")
            self.emit("")
            return
        if "type" in e.attrib:
            q = e.attrib.get("type", "")
            loc = qlocal(q)
            base = self.type_for_decl(q, as_field=False)
            if not self.m.is_builtin_q(q):
                base = go_name(loc, self.m.make_public)
                if base == name:
                    return
            self.emit_doc(e)
            self.emit(f"type {name} {base}")
            self.render_date_methods(name, base)
            self.emit("")

    def type_for_decl(self, q: str, as_field: bool = True) -> str:
        if self.m.is_builtin_q(q):
            return self.m.builtin_go(q)
        return go_name(qlocal(q), self.m.make_public)

    def field_type_for_element(self, elem: ET.Element, schema_ns: str) -> str:
        maxo = elem.attrib.get("maxOccurs", "")
        is_array = maxo not in ("", "1")
        nillable = elem.attrib.get("nillable", "false").lower() == "true"
        # Inline complex type.
        ct = first_child(elem, "complexType")
        if ct is not None:
            inner = self.render_anonymous_struct(ct, schema_ns, indent="")
            return "[]" + inner if is_array else inner
        # Inline simple type for local fields: use base, not a generated enum.
        st = first_child(elem, "simpleType")
        if st is not None:
            base, _, _ = self.simple_base(st)
            return ("[]" + base) if is_array else base
        q = elem.attrib.get("type", "")
        if not q and elem.attrib.get("ref"):
            ref = qlocal(elem.attrib.get("ref"))
            if ref in self.m.element_by_name:
                ref_el = self.m.element_by_name[ref].elem
                q = ref_el.attrib.get("type", "")
                if not q:
                    # Referenced inline global element is represented by its own name.
                    q = ref
                    base = go_name(ref, self.m.make_public)
                    return self.array_type(base, is_array, named=True, nillable=nillable)
                # If referenced global element has a generated alias (builtin or
                # simple), use the element name rather than raw builtin.
                if self.m.is_builtin_q(q) or qlocal(q) in self.m.simple_by_name:
                    base = go_name(ref, self.m.make_public)
                    return self.array_type(base, is_array, named=True, nillable=nillable)
        if not q:
            return "string"
        if self.m.is_builtin_q(q):
            base = self.m.builtin_go(q)
            return self.array_type(base, is_array, named=False, nillable=nillable)
        base = go_name(qlocal(q), self.m.make_public)
        return self.array_type(base, is_array, named=True, nillable=nillable)

    def array_type(self, base: str, is_array: bool, named: bool, nillable: bool) -> str:
        if is_array:
            if named:
                return "[]*" + base
            if nillable and not base.startswith("[]"):
                return "[]*" + base
            return "[]" + base
        if named:
            return "*" + base
        return base

    def field_name_for_element(self, elem: ET.Element) -> str:
        n = elem.attrib.get("name") or qlocal(elem.attrib.get("ref", ""))
        return go_name(n, self.m.make_public)

    def xml_tag_for_element(self, elem: ET.Element) -> str:
        n = elem.attrib.get("name") or qlocal(elem.attrib.get("ref", ""))
        return f'`xml:"{n},omitempty" json:"{n},omitempty"`'

    def render_field_for_element(self, elem: ET.Element, schema_ns: str, indent: str = "\t"):
        self.emit_doc(elem, indent)
        fname = self.field_name_for_element(elem)
        ftype = self.field_type_for_element(elem, schema_ns)
        tag = self.xml_tag_for_element(elem)
        # Anonymous struct type may be multi-line.  It is returned as literal with
        # embedded newlines and tabs relative to column zero; indent each line.
        if "\n" in ftype:
            lines = ftype.split("\n")
            self.emit(f"{indent}{fname} {lines[0]}")
            for ln in lines[1:]:
                self.emit(indent + ln)
            # Last line is closing }; append tag to it.
            self.lines[-1] += f" {tag}"
        else:
            self.emit(f"{indent}{fname} {ftype} {tag}")
        self.emit("")

    def attr_type(self, attr: ET.Element) -> str:
        q = attr.attrib.get("type", "")
        if not q:
            st = first_child(attr, "simpleType")
            if st is not None:
                base, _, _ = self.simple_base(st)
                return base
            ref = attr.attrib.get("ref", "")
            if ref:
                loc = qlocal(ref)
                if loc in self.m.attribute_by_name:
                    return self.attr_type(self.m.attribute_by_name[loc].elem)
                return "string"
            return "string"
        if self.m.is_builtin_q(q):
            return self.m.builtin_go(q)
        return "*" + go_name(qlocal(q), self.m.make_public)

    def attr_name(self, attr: ET.Element) -> str:
        if attr.attrib.get("name"):
            return attr.attrib.get("name", "")
        if attr.attrib.get("ref"):
            return qlocal(attr.attrib.get("ref", ""))
        return ""

    def render_attribute(self, attr: ET.Element, schema_ns: str, indent: str = "\t"):
        self.emit_doc(attr, indent)
        an = self.attr_name(attr)
        if not an:
            return
        fname = go_name(an, self.m.make_public)
        ftype = self.attr_type(attr)
        ns = schema_ns
        if attr.attrib.get("ref"):
            loc = qlocal(attr.attrib.get("ref"))
            if loc in self.m.attribute_by_name:
                ns = self.m.attribute_by_name[loc].ns
        self.emit(f"{indent}{fname} {ftype} `xml:\"{ns} {an},attr,omitempty\" json:\"{an},omitempty\"`")
        self.emit("")

    def render_anonymous_struct(self, ct: ET.Element, schema_ns: str, indent: str = "") -> str:
        sub = Generator(self.m, self.package)
        sub.lines = []
        sub.emit("struct {")
        sub.render_complex_body(ct, schema_ns, indent="\t", skip_xmlname=True)
        # Remove terminal blank before close for nicer inline output.
        while sub.lines and sub.lines[-1] == "":
            sub.lines.pop()
        sub.emit("}")
        return "\n".join(sub.lines)

    def render_complex_type(self, ct: SchemaThing):
        name = go_name(ct.name, self.m.make_public)
        self.emit_doc(ct.elem)
        self.emit(f"type {name} struct {{")
        if name in self.m.xmlname_for_type:
            ns, en = self.m.xmlname_for_type[name]
            self.emit(f"\tXMLName xml.Name `xml:\"{ns} {en}\"`")
            self.emit("")
        self.render_complex_body(ct.elem, ct.ns, indent="\t", skip_xmlname=True)
        while self.lines and self.lines[-1] == "":
            # Keep one blank before closing? Observed has no blank just before }
            self.lines.pop()
        self.emit("}")
        self.emit("")

    def render_complex_body(self, elem: ET.Element, schema_ns: str, indent: str = "\t", skip_xmlname: bool = False):
        # complexContent extension
        cc = first_child(elem, "complexContent")
        if cc is not None:
            ext = first_child(cc, "extension", "restriction")
            if ext is not None:
                base = ext.attrib.get("base", "")
                if base:
                    bname = self.type_for_decl(base)
                    self.emit(f"{indent}*{bname}")
                    self.emit("")
                self.render_particles_and_attrs(ext, schema_ns, indent)
                return
        sc = first_child(elem, "simpleContent")
        if sc is not None:
            ext = first_child(sc, "extension", "restriction")
            if ext is not None:
                base = ext.attrib.get("base", "string")
                if self.m.is_builtin_q(base):
                    btype = self.m.builtin_go(base)
                else:
                    btype = "*" + go_name(qlocal(base), self.m.make_public)
                self.emit(f"{indent}Value {btype} `xml:\",chardata\" json:\"-,\"`")
                self.emit("")
                for a in child_elems(ext, "attribute"):
                    self.render_attribute(a, schema_ns, indent)
                for ag in child_elems(ext, "attributeGroup"):
                    pass
                return
        self.render_particles_and_attrs(elem, schema_ns, indent)

    def render_particles_and_attrs(self, elem: ET.Element, schema_ns: str, indent: str):
        # Direct particles in order: sequence/all/choice elements, then attributes.
        for part in list(elem):
            ln = local_name(part.tag)
            if ln in ("sequence", "all", "choice"):
                for e in child_elems(part, "element"):
                    self.render_field_for_element(e, schema_ns, indent)
            elif ln == "element":
                self.render_field_for_element(part, schema_ns, indent)
            # Some schemas nest choice inside sequence.
            if ln in ("sequence", "all", "choice"):
                for nested in list(part):
                    if local_name(nested.tag) in ("choice", "sequence", "all"):
                        for e in child_elems(nested, "element"):
                            self.render_field_for_element(e, schema_ns, indent)
        for a in child_elems(elem, "attribute"):
            self.render_attribute(a, schema_ns, indent)

    def render_port_type(self, pt: PortType):
        if not pt.name:
            return
        iname = go_name(pt.name, True)
        self.emit(f"type {iname} interface {{")
        for op in pt.operations:
            req = self.m.message_type(op.input_msg)
            resp = self.m.message_type(op.output_msg)
            mname = go_name(op.name, True)
            if op.doc:
                self.emit("")
                # Observed operation comments are block comments in interfaces.
                doc = " ".join(x.strip() for x in op.doc.splitlines() if x.strip())
                self.emit(f"\t/* {doc} */")
            self.emit(f"\t{mname}(request *{req}) (*{resp}, error)")
            self.emit("")
            self.emit(f"\t{mname}Context(ctx context.Context, request *{req}) (*{resp}, error)")
            self.emit("")
        while self.lines and self.lines[-1] == "":
            self.lines.pop()
        self.emit("}")
        self.emit("")
        sname = private_name(pt.name)
        self.emit(f"type {sname} struct {{")
        self.emit("\tclient *soap.Client")
        self.emit("}")
        self.emit("")
        self.emit(f"func New{iname}(client *soap.Client) {iname} {{")
        self.emit(f"\treturn &{sname}{{")
        self.emit("\t\tclient: client,")
        self.emit("\t}")
        self.emit("}")
        self.emit("")
        for op in pt.operations:
            req = self.m.message_type(op.input_msg)
            resp = self.m.message_type(op.output_msg)
            mname = go_name(op.name, True)
            action = self.m.actions_by_port.get(pt.name, {}).get(op.name, "")
            action_lit = "''" if action == "" else action
            self.emit(f"func (service *{sname}) {mname}Context(ctx context.Context, request *{req}) (*{resp}, error) {{")
            self.emit(f"\tresponse := new({resp})")
            self.emit(f"\terr := service.client.CallContext(ctx, {quote_go_string(action_lit)}, request, response)")
            self.emit("\tif err != nil {")
            self.emit("\t\treturn nil, err")
            self.emit("\t}")
            self.emit("")
            self.emit("\treturn response, nil")
            self.emit("}")
            self.emit("")
            self.emit(f"func (service *{sname}) {mname}(request *{req}) (*{resp}, error) {{")
            self.emit(f"\treturn service.{mname}Context(")
            self.emit("\t\tcontext.Background(),")
            self.emit("\t\trequest,")
            self.emit("\t)")
            self.emit("}")
            self.emit("")


class ServerGenerator:
    def __init__(self, model: WsdlModel, package: str):
        self.m = model
        self.package = package
        self.lines: List[str] = []

    def emit(self, s: str = ""):
        self.lines.append(s)

    def operations(self) -> List[Tuple[str, str]]:
        ops = []
        for pt in self.m.port_types:
            for op in pt.operations:
                req = self.m.message_type(op.input_msg)
                resp = self.m.message_type(op.output_msg)
                ops.append((req, resp))
        return ops

    def render(self) -> str:
        self.lines = []
        self.emit("// Code generated by gowsdl DO NOT EDIT.")
        self.emit("")
        self.emit(f"package {self.package}")
        self.emit("")
        self.emit("import (")
        self.emit('\t"encoding/xml"')
        self.emit('\t"errors"')
        self.emit('\t"fmt"')
        self.emit('\t"net/http"')
        self.emit('\t"reflect"')
        self.emit('\t"strings"')
        self.emit(")")
        self.emit("")
        # Raw string embedding; if a backtick appears, degrade to quoted string.
        if "`" not in self.m.text:
            self.emit("var wsdl = `" + self.m.text + "`")
        else:
            self.emit("var wsdl = " + quote_go_string(self.m.text))
        self.emit("")
        self.emit('var WSDLUndefinedError = errors.New("Server was unable to process request. --> Object reference not set to an instance of an object.")')
        self.emit("")
        self.emit("type SOAPEnvelopeRequest struct {")
        self.emit('\tXMLName xml.Name `xml:"http://schemas.xmlsoap.org/soap/envelope/ Envelope"`')
        self.emit("\tBody    SOAPBodyRequest")
        self.emit("}")
        self.emit("")
        self.emit("type SOAPBodyRequest struct {")
        self.emit('\tXMLName xml.Name `xml:"http://schemas.xmlsoap.org/soap/envelope/ Body"`')
        self.emit("")
        for req, _ in self.operations():
            self.emit(f"\t{req} *{req} `xml:,omitempty`")
            self.emit("")
        while self.lines and self.lines[-1] == "":
            self.lines.pop()
        self.emit("}")
        self.emit("")
        self.emit("type SOAPEnvelopeResponse struct {")
        self.emit('\tXMLName    xml.Name `xml:"soap:Envelope"`')
        self.emit('\tPrefixSoap string   `xml:"xmlns:soap,attr"`')
        self.emit('\tPrefixXsi  string   `xml:"xmlns:xsi,attr"`')
        self.emit('\tPrefixXsd  string   `xml:"xmlns:xsd,attr"`')
        self.emit("")
        self.emit("\tBody SOAPBodyResponse")
        self.emit("}")
        self.emit("")
        self.emit("func NewSOAPEnvelopResponse() *SOAPEnvelopeResponse {")
        self.emit("\treturn &SOAPEnvelopeResponse{")
        self.emit('\t\tPrefixSoap: "http://schemas.xmlsoap.org/soap/envelope/",')
        self.emit('\t\tPrefixXsd:  "http://www.w3.org/2001/XMLSchema",')
        self.emit('\t\tPrefixXsi:  "http://www.w3.org/2001/XMLSchema-instance",')
        self.emit("\t}")
        self.emit("}")
        self.emit("")
        self.emit("type Fault struct {")
        self.emit('\tXMLName xml.Name `xml:"SOAP-ENV:Fault"`')
        self.emit('\tSpace   string   `xml:"xmlns:SOAP-ENV,omitempty,attr"`')
        self.emit("")
        self.emit('\tCode   string `xml:"faultcode,omitempty"`')
        self.emit('\tString string `xml:"faultstring,omitempty"`')
        self.emit('\tActor  string `xml:"faultactor,omitempty"`')
        self.emit('\tDetail string `xml:"detail,omitempty"`')
        self.emit("}")
        self.emit("")
        self.emit("type SOAPBodyResponse struct {")
        self.emit('\tXMLName xml.Name `xml:"soap:Body"`')
        self.emit('\tFault   *Fault   `xml:",omitempty"`')
        self.emit("")
        for req, resp in self.operations():
            self.emit(f"\t{req} *{resp} `xml:\",omitempty\"`")
            self.emit("")
        while self.lines and self.lines[-1] == "":
            self.lines.pop()
        self.emit("}")
        self.emit("")
        for req, resp in self.operations():
            self.emit(f"func (service *SOAPBodyRequest) {req}Func(request *{req}) (*{resp}, error) {{")
            self.emit("\treturn nil, WSDLUndefinedError")
            self.emit("}")
            self.emit("")
        self.emit_call_func()
        return "\n".join(self.lines).rstrip() + "\n"

    def emit_call_func(self):
        self.emit("func (service *SOAPEnvelopeRequest) call(w http.ResponseWriter, r *http.Request) {")
        self.emit('\tw.Header().Add("Content-Type", "text/xml; charset=utf-8")')
        self.emit("\tval := reflect.ValueOf(&service.Body).Elem()")
        self.emit("\tn := val.NumField()")
        self.emit("\tvar field reflect.Value")
        self.emit("\tvar name string")
        self.emit("\tfind := false")
        self.emit("")
        self.emit("\tif r.Method == http.MethodGet {")
        self.emit("\t\tw.Write([]byte(wsdl))")
        self.emit("\t\treturn")
        self.emit("\t}")
        self.emit("")
        self.emit("\tresp := NewSOAPEnvelopResponse()")
        self.emit("\tdefer func() {")
