class Loader:
    def __init__(self, skip_tls: bool = False):
        self.skip_tls = skip_tls
        self.loaded: List[LoadedDoc] = []
        self.seen: set[str] = set()

    def load_main(self, source: str) -> LoadedDoc:
        doc = self.load(source, None)
        return doc

    def display_path(self, source: str, base: Optional[str]) -> str:
        if is_url(source):
            return source
        if base and not is_url(base) and not os.path.isabs(source):
            source = os.path.join(os.path.dirname(base), source)
        return os.path.abspath(source)

    def resolve(self, source: str, base: Optional[str]) -> str:
        if is_url(source):
            return source
        if base and is_url(base):
            return urllib.parse.urljoin(base, source)
        if base and not os.path.isabs(source):
            return os.path.abspath(os.path.join(os.path.dirname(base), source))
        return os.path.abspath(source)

    def load(self, source: str, base: Optional[str]) -> LoadedDoc:
        resolved = self.resolve(source, base)
        if resolved in self.seen:
            # Return existing doc.
            for d in self.loaded:
                if d.base == resolved:
                    return d
        if is_url(resolved):
            print(f"🍀  Downloading file {resolved}")
            try:
                ctx = ssl._create_unverified_context() if self.skip_tls else None
                with urllib.request.urlopen(resolved, context=ctx) as r:
                    data = r.read()
            except Exception as e:
                raise RuntimeError(str(e))
            text = data.decode("utf-8", errors="replace")
            isurl = True
        else:
            print(f"🍀  Reading file {resolved}")
            try:
                with open(resolved, "rb") as f:
                    data = f.read()
            except OSError as e:
                # Match Go's open/read-ish errors closely enough.
                raise RuntimeError(f"open {resolved}: {e.strerror.lower() if e.strerror else e}")
            try:
                text = data.decode("utf-8")
            except UnicodeDecodeError:
                text = data.decode("utf-8", errors="replace")
            isurl = False
        try:
            root = ET.fromstring(text.encode("utf-8"))
        except ET.ParseError as e:
            # ElementTree messages differ from Go's; produce a concise parse error.
            raise RuntimeError(str(e))
        doc = LoadedDoc(text=text, root=root, base=resolved, is_url=isurl)
        self.loaded.append(doc)
        self.seen.add(resolved)
        # Recursively load schema imports/includes with schemaLocation.
        for schema in ([root] if local_name(root.tag) == "schema" else [x for x in root.iter() if local_name(x.tag) == "schema"]):
            for c in list(schema):
                if local_name(c.tag) in ("import", "include"):
                    loc = c.attrib.get("schemaLocation", "")
                    if loc:
                        self.load(loc, resolved)
        return doc


USAGE_TEMPLATE = """Usage: {prog} [options] myservice.wsdl
  -d string
    	Directory under which package directory will be created (default "./")
  -i	Skips TLS Verification
  -make-public
    	Make the generated types public/exported (default true)
  -o string
    	File where the generated code will be saved (default "myservice.go")
  -p string
    	Package under which code will be generated (default "myservice")
  -v	Shows gowsdl version
"""


def print_usage(prog: str):
    sys.stderr.write(USAGE_TEMPLATE.format(prog=prog))


def parse_go_bool(s: str) -> bool:
    sl = s.lower()
    if sl in ("1", "t", "true", "y", "yes"):
        return True
    if sl in ("0", "f", "false", "n", "no"):
        return False
    raise ValueError(f"parse error")


def parse_flags(argv: List[str]) -> Tuple[Optional[dict], int]:
    # Emulate Go's flag package sufficiently: parse flags until first non-flag;
    # bool flags may be -x or -x=value; string flags consume next arg.
    opts = {"d": "./", "i": False, "make-public": True, "o": "myservice.go", "p": "myservice", "v": False}
    i = 0
    while i < len(argv):
        a = argv[i]
        if a == "--":
            break
        if not a.startswith("-") or a == "-":
            break
        # Go accepts --help as -help; unknown --version reports -version.
        raw = a[2:] if a.startswith("--") else a[1:]
        name, eq, val = raw.partition("=")
        if name in ("h", "help"):
            print_usage(sys.argv[0])
            return None, 0
        if name in ("d", "o", "p"):
            if eq:
                opts[name] = val
            else:
                if i + 1 >= len(argv):
                    sys.stderr.write(f"flag needs an argument: -{name}\n")
                    print_usage(sys.argv[0])
                    return None, 2
                i += 1
                opts[name] = argv[i]
        elif name in ("i", "v", "make-public"):
            if eq:
                try:
                    opts[name] = parse_go_bool(val)
                except Exception:
                    sys.stderr.write(f"invalid boolean value {val!r} for -{name}\n")
                    print_usage(sys.argv[0])
                    return None, 2
            else:
                opts[name] = True
        else:
            sys.stderr.write(f"flag provided but not defined: -{name}\n")
            print_usage(sys.argv[0])
            return None, 2
        i += 1
    return opts, -1


def gofmt_file(path: str):
    gofmt = shutil.which("gofmt")
    if not gofmt:
        return
    try:
        subprocess.run([gofmt, "-w", path], stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL, check=False)
    except Exception:
        pass


def generate(opts: dict, wsdl_arg: str) -> int:
    if opts["o"] == wsdl_arg:
        print("🍀  Output file cannot be the same WSDL file")
        return 1
    loader = Loader(skip_tls=opts.get("i", False))
    try:
        main_doc = loader.load_main(wsdl_arg)
    except RuntimeError as e:
        print(f"🍀  {e}")
        return 1
    try:
        model = WsdlModel(main_doc.text, main_doc.root, wsdl_arg, loader.loaded, make_public=opts.get("make-public", True))
        gen = Generator(model, opts["p"])
        client = gen.render()
        sgen = ServerGenerator(model, opts["p"])
        server = sgen.render()
        pkg_dir = os.path.join(opts["d"], opts["p"])
        try:
            os.mkdir(pkg_dir)
        except Exception:
            pass
        out_path = os.path.join(pkg_dir, opts["o"])
        try:
            with open(out_path, "w", encoding="utf-8") as f:
                f.write(client)
        except OSError as e:
            print(f"🍀  open {out_path}: {e.strerror.lower() if e.strerror else e}")
            return 1
        gofmt_file(out_path)
        server_path = os.path.join(pkg_dir, "server" + opts["o"])
        try:
            with open(server_path, "w", encoding="utf-8") as f:
                f.write(server)
        except OSError as e:
            print(f"🍀  open {server_path}: {e.strerror.lower() if e.strerror else e}")
            return 1
        gofmt_file(server_path)
    except Exception as e:
        print(f"🍀  {e}")
        return 1
    print("🍀  Done 👍")
    return 0


def main() -> int:
    argv = sys.argv[1:]
    if len(argv) == 0:
        print_usage(sys.argv[0])
        return 0
    opts, status = parse_flags(argv)
    if opts is None:
        return status
    if opts.get("v"):
        print("🍀  v0.5.0")
        return 0
    # Observed executable uses the last raw argument as the WSDL path even if it
    # was consumed as a flag value.
    wsdl_arg = argv[-1]
    return generate(opts, wsdl_arg)


if __name__ == "__main__":
    sys.exit(main())
